                                     'Nhóm đất nền có MOS cao đang nằm quanh vùng 8.7-22.9 tr/m², so với giá trung vị đất nền 16.9 tr/m². '
                                     'Đây là nhóm đáng mở chi tiết trước, nhưng cần kiểm tra vị trí hẻm, thổ cư và quy hoạch trước khi xem '
                                     'là cơ hội thật.',
                                     'Nhóm nhà đất có MOS cao nằm quanh vùng 13.6-24.8 tr/m², so với giá trung vị nhà đất 23.1 tr/m². Với '
                                     'nhà đất, chênh lệch có thể đến từ tình trạng căn nhà hoặc pháp lý, nên cần xem ảnh, mô tả và thực '
