                              'Giá trung vị nhà đất 23.1 tr/m² cao hơn đất nền 16.9 tr/m² vì đã bao gồm tài sản trên đất. Sự chênh lệch '
                              'này là bình thường; điều quan trọng là so trong cùng loại hình để tránh kết luận sai.',
                              'Đất nền phù hợp làm mốc giá nền của phường, còn nhà đất cần đọc thêm chất lượng nhà, đường vào, pháp lý và '
