                                     'Nhóm đất nền có MOS cao đang nằm quanh vùng 10.2-21.2 tr/m², so với giá trung vị đất nền 23.6 tr/m². '
                                     'Đây là nhóm đáng mở chi tiết trước, nhưng cần kiểm tra vị trí hẻm, thổ cư và quy hoạch trước khi xem '
                                     'là cơ hội thật.',
                                     'Nhóm nhà đất có MOS cao nằm quanh vùng 16.1-30.0 tr/m², so với giá trung vị nhà đất 39.4 tr/m². Với '
